import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"示例项目索引","description":"一对一映射 TS-AI 手册内模块最小骨架与实战项目示例，按能力反查示例路径","frontmatter":{"title":"示例项目索引","description":"一对一映射 TS-AI 手册内模块最小骨架与实战项目示例，按能力反查示例路径","article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/appendix/references/examples-index.md","filePath":"ts-ai/appendix/references/examples-index.md","lastUpdated":1786166505000}'),s={name:"ts-ai/appendix/references/examples-index.md"};function n(i,t,l,o,p,c){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="示例项目索引" tabindex="-1">示例项目索引 <a class="header-anchor" href="#示例项目索引" aria-label="Permalink to &quot;示例项目索引&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本索引只指向<strong>本手册已有文章路径</strong>，不另开外部 Demo 仓库宇宙。先跑模块内最小骨架，再把必修基线项目做完；不要多线并行。</p><p>项目分层说明见 <a href="/ts-ai/architecture/">架构与实战总览</a>；版本主线见 <a href="/ts-ai/appendix/references/technology-stack-compatibility">技术栈与版本兼容表</a>。</p><h2 id="_1-怎么用" tabindex="-1">1. 怎么用 <a class="header-anchor" href="#_1-怎么用" aria-label="Permalink to &quot;1. 怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的目标</th><th>起点</th></tr></thead><tbody><tr><td>第一次把环境跑通</td><td>§2 基础与 Agent 最小骨架</td></tr><tr><td>证明全栈协议（SSE / Thread / Run）</td><td><a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a></td></tr><tr><td>在底座上证对外问答：引用 / 拒答 / 反馈</td><td>P2 产品帮助中心问答（规划中），先补 <a href="/ts-ai/knowledge/rag-foundations/minimal-rag-skeleton">最小 RAG</a></td></tr><tr><td>在底座上证长任务与人机确认</td><td>P3 深度研究报告（规划中），先补 <a href="/ts-ai/workflow/workflow-foundations/minimal-stategraph-skeleton">最小 StateGraph</a></td></tr><tr><td>在底座上证查数与 MCP 治理</td><td>P4 经营数据分析（规划中），先补 §2 模块骨架</td></tr><tr><td>基线通后再做多角色</td><td>P5 内容审校流水线（可选，规划中）</td></tr><tr><td>按能力反查</td><td>§4</td></tr></tbody></table><p>建议路径：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模块最小骨架</span></span>
<span class="line"><span>  → 实战 · AI 客服中心（必修基线，成品参考 examples/ts-ai/ai-customer-support/final）</span></span>
<span class="line"><span>       ├─→ P2 产品帮助中心问答（对外 RAG）</span></span>
<span class="line"><span>       ├─→ P3 深度研究报告（长任务）</span></span>
<span class="line"><span>       ├─→ P4 经营数据分析（MCP 治理）</span></span>
<span class="line"><span>       └─→（可选）P5 内容审校流水线</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="_2-模块内最小骨架" tabindex="-1">2. 模块内最小骨架 <a class="header-anchor" href="#_2-模块内最小骨架" aria-label="Permalink to &quot;2. 模块内最小骨架&quot;">​</a></h2><p>下列文章是各模块的<strong>最小可运行入口</strong>；升级依赖或排障时优先回归这里。</p><table tabindex="0"><thead><tr><th>模块</th><th>最小骨架（手册路径）</th><th>跑通后应能验证</th></tr></thead><tbody><tr><td>基础与模型</td><td><a href="/ts-ai/foundations/getting-started/create-typescript-ai-project">创建 TypeScript AI 项目</a></td><td>Node 22+、ESM、类型检查与 Vitest 入口可用</td></tr><tr><td>基础与模型</td><td><a href="/ts-ai/foundations/langchain-bridge/first-chatopenai-invoke">第一次 <code>ChatOpenAI.invoke()</code></a></td><td>一次真实或可配置的模型调用与错误处理</td></tr><tr><td>基础与模型</td><td><a href="/ts-ai/foundations/langchain-bridge/zod-structured-output">使用 Zod 获取结构化输出</a></td><td>Schema 约束输出并通过业务校验</td></tr><tr><td>Agent 开发</td><td><a href="/ts-ai/agent/runtime/create-agent">使用 createAgent 创建 Agent</a></td><td>最小 Agent + Tool 闭环</td></tr><tr><td>服务端工程</td><td><a href="/ts-ai/backend/nestjs-core/minimal-agent-api-skeleton">最小可运行 Agent API</a></td><td>Nest 模块、鉴权 Stub、HTTP 返回 <code>runId</code> + reply</td></tr><tr><td>RAG 与记忆</td><td><a href="/ts-ai/knowledge/rag-foundations/minimal-rag-skeleton">最小可运行 RAG</a></td><td>固定语料检索 → 组装上下文 → 生成</td></tr><tr><td>工作流与多 Agent</td><td><a href="/ts-ai/workflow/workflow-foundations/minimal-stategraph-skeleton">最小可运行 StateGraph</a></td><td><code>compile</code> + <code>invoke</code>，分支路径符合预期</td></tr><tr><td>全栈集成</td><td><a href="/ts-ai/integration/vue-nuxt/minimal-ai-chat-ui">最小可运行 AI Chat UI</a></td><td>消费假事件流，流式状态机可用</td></tr></tbody></table><p>组装配方（非“最小骨架”，但是模块收束清单）：</p><table tabindex="0"><thead><tr><th>模块</th><th>组装配方</th></tr></thead><tbody><tr><td>Agent</td><td><a href="/ts-ai/agent/assembly/assembly-recipes-checklist">Agent 组装配方与能力自检</a></td></tr><tr><td>服务端</td><td><a href="/ts-ai/backend/assembly/assembly-recipes-checklist">AI 服务组装配方与能力自检</a></td></tr><tr><td>RAG 与记忆</td><td><a href="/ts-ai/knowledge/assembly/assembly-recipes-checklist">RAG 与记忆组装配方与能力自检</a></td></tr><tr><td>工作流</td><td><a href="/ts-ai/workflow/assembly/assembly-recipes-checklist">工作流与多 Agent 组装配方与能力自检</a></td></tr><tr><td>全栈集成</td><td><a href="/ts-ai/integration/assembly/assembly-recipes-checklist">全栈集成组装配方与能力自检</a></td></tr><tr><td>质量与生产</td><td><a href="/ts-ai/quality/assembly/assembly-recipes-checklist">质量与生产组装配方与能力自检</a></td></tr><tr><td>架构与实战</td><td><a href="/ts-ai/architecture/assembly/assembly-recipes-checklist">架构与实战组装配方与能力自检</a></td></tr></tbody></table><h2 id="_3-实战项目" tabindex="-1">3. 实战项目 <a class="header-anchor" href="#_3-实战项目" aria-label="Permalink to &quot;3. 实战项目&quot;">​</a></h2><p>与 <code>docs/.vitepress/ts-ai-routes.mjs</code> 中 <code>ai-customer-support</code> 分组对应；章末成品参考为 <code>examples/ts-ai/ai-customer-support/final</code>；P2–P5 规划见 <a href="/ts-ai/architecture/">架构与实战总览</a>。</p><table tabindex="0"><thead><tr><th>层级</th><th>项目</th><th>手册路径</th><th>相对共用底座的技术增量</th><th>主验收模块</th></tr></thead><tbody><tr><td>必修基线（P1）</td><td>AI 客服中心</td><td><a href="/ts-ai/architecture/ai-customer-support/">/ts-ai/architecture/ai-customer-support/</a></td><td>Thread/Run、Nest SSE、取消重连、租户鉴权、Model Gateway、分诊建工单、Nuxt Chat</td><td>backend + integration + quality</td></tr><tr><td>P2（正文待写）</td><td>产品帮助中心问答</td><td>规划见总览</td><td>对外 RAG、引用、嵌入式组件、反馈闭环</td><td>knowledge</td></tr><tr><td>P3（正文待写）</td><td>深度研究报告</td><td>规划见总览</td><td>长任务队列、Interrupt、检查点、报告引用</td><td>workflow</td></tr><tr><td>P4（正文待写）</td><td>经营数据分析</td><td>规划见总览</td><td>数据 MCP Server、网关治理、NL→SQL、只读护栏</td><td>tools-mcp + 结构化输出</td></tr><tr><td>P5 可选（正文待写）</td><td>多角色内容审校</td><td>规划见总览</td><td>Supervisor、预算守卫、对照实验</td><td>multi-agent + 评测门禁</td></tr></tbody></table><p>共用底座（基线与后续项目共享）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TypeScript + Vue 3/Nuxt + NestJS</span></span>
<span class="line"><span>  + LangChain.js（Gateway / 最小 Agent）</span></span>
<span class="line"><span>  + PostgreSQL（Thread/Run/Message）</span></span>
<span class="line"><span>  + 自建产品 SSE 事件</span></span>
<span class="line"><span>  + 评测门禁与关联 ID 日志</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>选定项目后的交付文档：<a href="/ts-ai/architecture/delivery/">项目交付</a>。</p><h2 id="_4-按能力找示例" tabindex="-1">4. 按能力找示例 <a class="header-anchor" href="#_4-按能力找示例" aria-label="Permalink to &quot;4. 按能力找示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>优先最小骨架</th><th>优先实战项目</th><th>深入章节</th></tr></thead><tbody><tr><td>模型调用 / 结构化输出</td><td>foundations langchain-bridge</td><td>AI 客服中心（经 Gateway）</td><td><a href="/ts-ai/agent/models-output/">模型与输出</a></td></tr><tr><td>Agent + Tool</td><td>createAgent</td><td>AI 客服中心</td><td><a href="/ts-ai/agent/tools-mcp/">工具与 MCP</a></td></tr><tr><td>Nest Agent API</td><td>minimal-agent-api-skeleton</td><td>AI 客服中心</td><td><a href="/ts-ai/backend/ai-service/">AI 服务架构</a></td></tr><tr><td>SSE / 取消 / 重连</td><td>minimal-ai-chat-ui</td><td>AI 客服中心</td><td><a href="/ts-ai/integration/interaction-protocols/">交互协议</a></td></tr><tr><td>RAG / 引用 / 上传索引</td><td>minimal-rag-skeleton</td><td>P2 帮助中心问答（规划中）</td><td><a href="/ts-ai/knowledge/rag-engineering/">RAG 工程</a></td></tr><tr><td>StateGraph / Interrupt / HITL</td><td>minimal-stategraph-skeleton</td><td>P3 深度研究报告（规划中）</td><td><a href="/ts-ai/workflow/durable-execution/">持久执行</a></td></tr><tr><td>MCP 远程工具网关</td><td>mcp-typescript-sdk + langchain-mcp-integration</td><td>P4 经营数据分析（规划中）</td><td><a href="/ts-ai/agent/tools-mcp/langchain-mcp-integration">LangChain.js 集成 MCP</a></td></tr><tr><td>Supervisor / Handoff</td><td>（先单图骨架）</td><td>P5 内容审校（规划中）</td><td><a href="/ts-ai/workflow/multi-agent/">多 Agent</a></td></tr><tr><td>评测 / 观测 / 发布</td><td>（质量组装配方）</td><td>AI 客服中心收尾</td><td><a href="/ts-ai/quality/">质量与生产</a>、<a href="/ts-ai/architecture/delivery/">项目交付</a></td></tr></tbody></table><p>Research / Data-SQL 已由 P3 / P4 项目实战承接；多模态等其他领域形态见 <a href="/ts-ai/architecture/agent-types/">Agent 类型</a>。</p><h2 id="_5-关联章节" tabindex="-1">5. 关联章节 <a class="header-anchor" href="#_5-关联章节" aria-label="Permalink to &quot;5. 关联章节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>章节</th></tr></thead><tbody><tr><td>项目分层与建议路径</td><td><a href="/ts-ai/architecture/">架构与实战总览</a></td></tr><tr><td>学习顺序</td><td><a href="/ts-ai/appendix/learning/learning-roadmap">学习路线图</a></td></tr><tr><td>知识点勾选</td><td><a href="/ts-ai/appendix/learning/knowledge-checklist">知识点清单</a></td></tr><tr><td>官方文档入口</td><td><a href="/ts-ai/appendix/references/official-resources">官方资料索引</a></td></tr><tr><td>版本升级回归</td><td><a href="/ts-ai/appendix/references/technology-stack-compatibility">技术栈与版本兼容表</a> §7</td></tr></tbody></table>`,24)])])}const b=a(s,[["render",n]]);export{u as __pageData,b as default};
